172  /** 从磁盘读取并校验配置，错误信息不含 YAML 原文。 */
173  function readConfig(file: string): ConfigSnapshot {
174    //M 启动和重读共用同一份入口校验。
175    const yamlText = fs.readFileSync(file, 'utf8');
176    const document = yaml.parseDocument(yamlText);
177  
178    //G YAML 解析错误会带出原文，错误里只保留行号。
179    const broken = document.errors[0];
180    if (broken !== undefined) {
181      const line = String(broken.linePos?.[0].line ?? '?');
182      throw new Error(`config.yaml 不是合法的 YAML（第 ${line} 行附近）`);
183    }
184  
185    const written: unknown = document.toJSON();
186    //M 交给 checkConfig 校验一次。顶层确认是对象后，插件仍可读取原始值。
187    const config = checks.checkConfig(written);
188    const raw = written as Record<string, unknown>;
189    return { config, raw };
190  }
191  
192  
```

### 解释
- L175：读 config.yaml 原文。
- L179–L183：守卫：YAML 解析错误会带出原文，错误里只保留行号。
- L187：**外部入口**：交给 checkConfig 校验一次，之后内部直接用。
- L189：校验后的配置和原始对象一起交回。

