```ts
264    /** 按 ID 更新 pi 集合。密钥变动由请求时的解析回调处理。 */
265    private updateProviders(providers: JmbotsConfig['providers'], previous: JmbotsConfig['providers']): void {
266      //==========================================================
267      //M 准备新增或连接配置变更的供应商
268      //==========================================================
269      /**
270       * 待登记的 pi-ai `Provider` 实例连接模型目录、鉴权和请求。
271       * - `id` 是供应商标识，用于登记和查找。
272       * - `name` 是展示名。
273       * - `baseUrl` 可选，是请求的基础地址。
274       * - `auth` 提供供应商鉴权。
275       * - `getModels()` 同步读取当前已知的对话模型。
276       * - `streamSimple(model, context, options)` 发出对话请求并返回事件流。
277       * 全部字段见 node_modules/@earendil-works/pi-ai/dist/models.d.ts:72。
278       */
279      const created: piAi.Provider[] = [];
280      utils.eachEntry(providers, (name, provider) => {
281        const old = previous[name];
282        if (old?.baseUrl === provider.baseUrl && old.api === provider.api) return;
283  
284        //M 先建好新增或连接参数变动的供应商，再更新现有集合。
285        const getApi = CHAT_APIS[provider.api];
286        const api = getApi();
287        const auth = this.getProviderAuth(provider, name);
288        const options = {
289          id: name, baseUrl: provider.baseUrl, auth, models: [], api,
290        };
291        const item = piAi.createProvider(options);
292        created.push(item);
293      });
294  
295      //==========================================================
296      //M 把配置变更应用到运行中的供应商集合
297      //==========================================================
298      //M 移除配置里删掉的供应商，再登记准备好的新实现。
299      const configured = Object.keys(previous);
300      for (const name of configured) {
301        if (Object.hasOwn(providers, name)) continue;
302        this.models.deleteProvider(name);
303      }
304      for (const item of created) {
305        this.models.setProvider(item);
306      }
307    }
308  
```

### 解释
- 先建后换：新增或地址、协议变了的供应商先全部建好，再统一删旧、登记新，不会出现一半新一半旧。
- 密钥变动不用重建：请求时由鉴权回调现取当前配置。

