309    /** 监听 config.yaml，合并保存动作产生的多次文件通知。 */
310    private watchConfig(file: string): void {
311      this.ctx.effect(() => {
312        let pending: ReturnType<typeof setTimeout> | undefined;
313        //M 非持久监听与定时器让命令行模式能照常退出。
314        const watcher = fs.watch(this.root, { persistent: false }, (_event, name) => {
315          if (name !== null && name.toLowerCase() !== CONFIG_FILE) return;
316  
317          clearTimeout(pending);
318          pending = setTimeout(() => this.reloadConfig(file), CONFIG_RELOAD_DELAY_MS);
319          pending.unref();
320        });
321        watcher.on('error', (error) => {
322          console.error(`config.yaml 监听失败：${error.message}`);
323        });
324        return () => {
325          clearTimeout(pending);
326          watcher.close();
327        };
328      });
329    }
330  
```

### 解释
- L314：监听父目录（设置页用临时文件原子替换后仍能继续监听）；非持久监听让命令行模式能照常退出。
- L315：守卫：不是 config.yaml 的改动不管。
- L318：防抖：500 毫秒后才调重读。
- L326：服务被拔掉时收掉监听和定时器。

